/* ===== Emoji Only: Har house par chhota icon, click par list khulegi, emoji slow fly karega ===== */
(function(){
var wrap=document.getElementById('game-wrap');
var box=document.getElementById('emoji-houses');
if(!wrap||!box) return;
function activeColors(){
  var a=window.__ludoActive;
  if(a && a.length) return a;
  return ['red','blue','orange','green'];
}
function syncHouses(){
  // 4RON houses par icon - chahe koi bhi mode ho (1v1 me bhi sab dikhenge)
  box.querySelectorAll('.emoji-house').forEach(function(h){ h.style.display='block'; });
  box.style.display = (wrap.style.display==='block') ? 'block' : 'none';
}
function closeAllLists(except){
  box.querySelectorAll('.eh-list.open').forEach(function(l){ if(l!==except) l.classList.remove('open'); });
}
function houseCenter(houseEl){
  var r=houseEl.getBoundingClientRect();
  return {x:r.left + r.width/2, y:r.top + r.height/2};
}
function spawnFromHouse(houseEl, emoji){
  var c=houseCenter(houseEl);
  // 3 BAAR FLY: 3 waves, har wave ke beech 750ms ka gap
  for(var wave=0; wave<3; wave++){
    (function(wave){
      setTimeout(function(){
        for(var i=0;i<2;i++){
          (function(i){
            var el=document.createElement('div');
            el.className='emoji-fly';
            el.textContent=emoji;
            var startX = Math.max(30, Math.min(window.innerWidth-30, c.x + (i-0.5)*24));
            el.style.left=startX+'px';
            el.style.top=c.y+'px';
            el.style.opacity='1';
            document.body.appendChild(el);
            requestAnimationFrame(function(){
              setTimeout(function(){
                var inward = (houseEl.classList.contains('eh-blue')||houseEl.classList.contains('eh-orange')) ? -1 : 1;
                var dx = inward*(50 + Math.random()*60);
                var isTop = houseEl.classList.contains('eh-red')||houseEl.classList.contains('eh-blue');
                var dy = isTop ? (150 + Math.random()*90) : (-150 - Math.random()*90);
                el.style.transform='translate('+dx+'px,'+dy+'px) scale(2.2) rotate('+(inward*18)+'deg)';
                el.style.opacity='0';
              }, 30);
            });
            setTimeout(function(){ el.remove(); }, 3000);
          })(i);
        }
      }, wave*750);
    })(wave);
  }
}
box.addEventListener('click', function(e){
  var toggle=e.target.closest('.eh-toggle');
  if(toggle){
    var list=toggle.closest('.emoji-house').querySelector('.eh-list');
    var wasOpen=list.classList.contains('open');
    closeAllLists();
    if(!wasOpen) list.classList.add('open');
    return;
  }
  var btn=e.target.closest('button[data-emoji]');
  if(!btn) return;
  var houseEl=btn.closest('.emoji-house');
  spawnFromHouse(houseEl, btn.dataset.emoji);
  closeAllLists();
});
document.addEventListener('click', function(e){
  if(!e.target.closest('.emoji-house')) closeAllLists();
});
new MutationObserver(syncHouses).observe(wrap,{attributes:true,attributeFilter:['style']});
syncHouses();
})();

/* ================= Next <script> block ================= */

/* ===== Game Chat: message 7 second ke liye house ke paas dikhega ===== */
(function(){
  var input=document.getElementById('chat-input');
  var sendBtn=document.getElementById('chat-send');
  var count=document.getElementById('chat-count');
  var selectedHouse='red';
  if(!input||!sendBtn) return;
  var colors={red:'#ED1C24',blue:'#2196F3',green:'#4CAF50',orange:'#FF9800'};
  document.querySelectorAll('.chat-house').forEach(function(b){
    b.addEventListener('click',function(){
      selectedHouse=b.dataset.chatHouse;
      document.querySelectorAll('.chat-house').forEach(function(x){x.classList.toggle('active',x===b);});
    });
  });
  function updateCount(){
    count.textContent=input.value.length+'/30';
    sendBtn.disabled=!input.value.trim();
  }
  input.addEventListener('input',updateCount);
  updateCount();
  function sendChat(){
    var msg=input.value.trim();
    if(!msg) return;
    var house=document.querySelector('.emoji-house[data-house="'+selectedHouse+'"]');
    var bubble=document.createElement('div');
    bubble.className='chat-bubble';
    bubble.textContent=msg;
    bubble.style.borderColor=colors[selectedHouse]||'#111';
    if(house){
      var r=house.getBoundingClientRect();
      var isTop=(selectedHouse==='red'||selectedHouse==='blue');
      var left=Math.max(8,Math.min(window.innerWidth-180,r.left-10));
      bubble.style.left=left+'px';
      if(isTop){ bubble.style.top=(r.bottom+8)+'px'; }
      else{ bubble.style.top=Math.max(8,r.top-52)+'px'; }
    }else{
      bubble.style.left='12px'; bubble.style.top='70px';
    }
    document.body.appendChild(bubble);
    setTimeout(function(){ bubble.remove(); },7000);
    input.value=''; updateCount(); input.focus();
  }
  sendBtn.addEventListener('click',sendChat);
  input.addEventListener('keydown',function(e){ if(e.key==='Enter') sendChat(); });
})();